    ("d3_samho_warn", 2, "say", "samho", "drunk", "에이, 이거 가지고 뭘 취해. 아직 두 잔밖에 안 마셨어어어.", "Pfft, drunk off this? I've only had two glasses sooo faaar.", "", "", ""),
    ("d3_samho_warn", 3, "say", "luna", "default", "세 잔입니다.", "That was three glasses.", "", "", ""),
    ("d3_samho_warn", 4, "say", "samho", "drunk", "그거나 그거나~", "Same difference~", "", "", ""),
    ("d3_samho_warn", 5, "say", "samho", "drunk", "아무튼 한 잔 정도야 괜찮아~", "Anyway, one more glass is fiiine~", "", "", "선택지 직전 — 삼호 대사(루나 규칙 OK)"),
