    ("d3_samho_pour", 8,  "craft", "", "order", "", "", "", "", ""),
    ("d3_samho_pour", 9,  "serve", "samho", "", "", "", "", "", ""),
    ("d3_samho_pour", 10, "say", "samho", "drunk", "크… 이거지. 너무 맛있는데? 이제 쓴맛도\n별로 안 느껴져. 보스가 왜 이걸 마시는지 알겠네.", "Ahh... that's the one. So good! I can barely taste\nthe bitterness now. I get why Boss drinks this.", "grade >= perfect", "", "d2sm_last_react_perfect_001"),
    ("d3_samho_pour", 11, "say", "samho", "drunk", "크… 이거지. 보스가 마시는 맛이야.", "Ahh... that's the one. The taste of the Boss.", "grade >= good && grade < perfect", "", "d2sm_last_react_good_001"),
